import openpyxl
from openpyxl.utils import get_column_letter

src='/root/data/workbook.xlsx'
dst='/root/output/result.xlsx'

wb=openpyxl.load_workbook(src, data_only=False)
wsT=wb['Task']

# Lookup formula template
# Data layout: series code in Data!D21:D38; year values in Data!H:L columns corresponding to 2020-2024
